class EnterprisePosCheckoutRequest extends FormRequest { public function authorize():bool{return auth()->check();} public function rules():array{return ['customer_id'=>['nullable','integer','exists:customers,id'],'discount'=>['nullable','numeric','min:0'],'tax'=>['nullable','numeric','min:0'],'shipping'=>['nullable','numeric','min:0'],'paid_amount'=>['nullable','numeric','min:0'],'payment_method'=>['nullable','string','in:Cash,Card,Mobile Banking,Bank'],'note'=>['nullable','string','max:1000'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id','distinct'],'items.*.quantity'=>['required','integer','min:1'],'payments'=>['nullable','array','min:1'],'payments.*.method'=>['required_with:payments','string','in:Cash,Card,Mobile Banking,Bank'],'payments.*.amount'=>['required_with:payments','numeric','min:0.01'],'payments.*.reference'=>['nullable','string','max:255']];} }
